#!/bin/bash
# Asks a guest whether it can actually reach what the policy denies.
#
#   probe-egress.sh <ruleset.nft> <tap-name>
#
# The ruleset is generated by AI17Z (`nftablesRuleset`) and passed in, so what
# is tested is the product's own output rather than something written here. The
# guest gets its own namespace and one tap, which is the shape a tenant runs
# in: nftables evaluates every chain at a hook, so two tenant tables in one
# namespace each drop the other's traffic through their own policy, and the lab
# must not quietly test a configuration the product never has.
#
# Idempotent: it stops anything it left behind before it starts.
set -euo pipefail

RULESET="${1:?usage: probe-egress.sh <ruleset.nft> <tap>}"
TAP="${2:?usage: probe-egress.sh <ruleset.nft> <tap>}"

LAB=/opt/ai17z-lab
ID=egress-probe
NS="ai17z-$ID"
LOG="$LAB/$ID.console.log"

say() { printf '  %s\n' "$*"; }

# ---------------------------------------------------------------------------
# Stop anything from a previous run. A guest that is still up holds its tap,
# which is what "resource busy" means, and the probe cannot be re-run until it
# lets go.
# ---------------------------------------------------------------------------
# Matched on `^/firecracker --id <this one>`, which is how the process's own
# command line begins. The bare word matches anything that mentions it,
# including whatever invoked this script, and `id $ID` matches any command line
# with those characters in it. Scoped to this probe's own guest as well, so
# running it never takes down a tenant somebody else is measuring.
pkill -f "^/usr/local/bin/jailer --id $ID" 2>/dev/null || true
for p in $(pgrep -f "^/firecracker --id $ID" 2>/dev/null || true); do
  kill -TERM "$p" 2>/dev/null || true
done
# Give them a moment, then insist.
for _ in $(seq 1 20); do
  pgrep -f "^/firecracker --id $ID" >/dev/null 2>&1 || break
  sleep 0.2
done
for p in $(pgrep -f "^/firecracker --id $ID" 2>/dev/null || true); do
  kill -KILL "$p" 2>/dev/null || true
done

ip netns del "$NS" 2>/dev/null || true
ip netns add "$NS"
ip netns exec "$NS" ip link set lo up
ip netns exec "$NS" ip tuntap add dev "$TAP" mode tap
ip netns exec "$NS" ip addr add 172.31.0.1/30 dev "$TAP"
ip netns exec "$NS" ip link set "$TAP" up

# The policy, loaded before the guest exists, from AI17Z's own output.
ip netns exec "$NS" nft -f "$RULESET"
LOADED=$(ip netns exec "$NS" nft list tables | grep -c ai17z_tenant || true)
say "tenant tables in the namespace: $LOADED (one is the product shape)"

# An uplink, so the permitted half can be tested by trying rather than assumed.
"$LAB/bin/uplink.sh" "$NS" "$TAP" >/dev/null 2>&1 || say "uplink setup reported a problem"
if ip netns exec "$NS" timeout 8 ping -c1 -W3 1.1.1.1 >/dev/null 2>&1; then
  say 'the namespace itself can reach the internet'
else
  say 'the namespace itself cannot reach the internet, so a blocked result below means nothing'
fi

# ---------------------------------------------------------------------------
# The guest. Its init is the probe, so there is nothing to type and nothing to
# wait on except the answer.
# ---------------------------------------------------------------------------
rm -rf "$LAB/jail/$ID"
JAIL="$LAB/jail/$ID/firecracker/$ID/root"
mkdir -p "$JAIL"
cp "$LAB/dl/vmlinux" "$JAIL/vmlinux"
cp "$LAB/dl/rootfs-egress.ext4" "$JAIL/rootfs.ext4"
cat > "$JAIL/config.json" <<JSON
{
  "boot-source": {
    "kernel_image_path": "vmlinux",
    "boot_args": "console=ttyS0 reboot=k panic=1 pci=off ip=172.31.0.2::172.31.0.1:255.255.255.252::eth0:off init=/ai17z-egress-test.sh"
  },
  "drives": [ { "drive_id": "rootfs", "path_on_host": "rootfs.ext4", "is_root_device": true, "is_read_only": false } ],
  "machine-config": { "vcpu_count": 1, "mem_size_mib": 512, "smt": false },
  "network-interfaces": [ { "iface_id": "eth0", "host_dev_name": "${TAP}" } ]
}
JSON
chown -R 10000:10000 "$LAB/jail/$ID"

: > "$LOG"
setsid jailer \
  --id "$ID" --exec-file /usr/local/bin/firecracker \
  --uid 10000 --gid 10000 \
  --chroot-base-dir "$LAB/jail/$ID" --netns "/var/run/netns/$NS" \
  -- --config-file config.json --no-api \
  > "$LOG" 2>&1 < /dev/null &

for _ in $(seq 1 250); do
  grep -q 'AI17Z-PROOF done' "$LOG" 2>/dev/null && break
  sleep 0.4
done

printf '\n'
if grep -q 'AI17Z-PROOF' "$LOG" 2>/dev/null; then
  grep 'AI17Z-PROOF' "$LOG" | sed 's/AI17Z-PROOF /  /'
else
  say 'the guest said nothing. last lines of its console:'
  tail -5 "$LOG" | tr -d '\000' | sed 's/^/    /'
fi

FAILED=$(grep -c 'AI17Z-PROOF FAIL' "$LOG" 2>/dev/null || true)
printf '\n'
if [ "${FAILED:-1}" = "0" ] && grep -q 'AI17Z-PROOF done' "$LOG" 2>/dev/null; then
  say 'Every probe matched the policy, from inside the guest.'
  exit 0
fi
say "${FAILED:-?} probe(s) did not match the policy."
exit 1
